package net.minecraft.nbt;import java.util.*;public class CompoundTag extends Tag { @Override public String toString(){return new java.util.TreeMap<>(m).toString();} private final Map<String,Object> m=new HashMap<>();public void putUUID(String k,UUID v){m.put(k,v);}public boolean hasUUID(String k){return m.get(k) instanceof UUID;}public UUID getUUID(String k){return (UUID)m.get(k);}public void putLong(String k,long v){m.put(k,v);}public long getLong(String k){return (Long)m.getOrDefault(k,0L);}public void putString(String k,String v){m.put(k,v);}public String getString(String k){return (String)m.getOrDefault(k,"");}public void putInt(String k,int v){m.put(k,v);}public int getInt(String k){return (Integer)m.getOrDefault(k,0);}public void putBoolean(String k,boolean v){m.put(k,v);}public boolean getBoolean(String k){return (Boolean)m.getOrDefault(k,false);}public void put(String k,ListTag v){m.put(k,v);}public ListTag getList(String k,int type){return (ListTag)m.getOrDefault(k,new ListTag());}public boolean contains(String k,int type){return m.containsKey(k);}}